WITH parsed AS (SELECT id, customer_id, created_at, ship_to, ARRAY_CONTAINS(coupon_codes, 'VIP') AS used_vip, FORALL(items, i -> i.qty <= 5) AS all_small_qty FROM carts WHERE TO_DATE(created_at) < '2023-08-11') SELECT *, ROW_NUMBER() OVER w_hist AS row_seq, ROW_NUMBER() OVER w_part AS event_seq, ROW_NUMBER() OVER w_hist AS event_seq_2, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY created_at DESC, id) AS seq_no, ROW_NUMBER() OVER w_hist AS event_seq_3 FROM parsed WINDOW w_hist AS (ORDER BY created_at, id), w_part AS (ORDER BY created_at DESC, id);
